<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { BookOpenCheck, CalendarDays, PencilLine, Trash2 } from '@lucide/vue'
import { useRouter } from 'vue-router'
import { studentService } from '../../services/studentService'
import { useLessonStore } from '../../stores/useLessonStore'
import { useWorkbenchStore } from '../../stores/workbench'
import type { Student } from '../../types/schema'
import LessonFormDrawer from './LessonFormDrawer.vue'

const lessonStore = useLessonStore(); const workbench = useWorkbenchStore(); const router = useRouter(); const students = ref<Student[]>([])
const lesson = computed(() => lessonStore.selectedLesson)
const observedStudents = computed(() => lesson.value?.notableStudents.map((item) => ({ ...item, student: students.value.find((student) => student.id === item.studentId) })).filter((item) => Boolean(item.student)) ?? [])
async function loadStudents() { students.value = await studentService.list() }
function startConsultation(student: Student, note: string) { workbench.pendingConsultationContext = { studentId: student.id, visitType: 'referral', subjective: `【心理课课堂观察】${lesson.value?.date ?? ''}《${lesson.value?.topic ?? ''}》课堂中观察到：${note || '需进一步了解的课堂表现。'}` }; router.push('/consultations') }
async function remove() { if (!lesson.value || !window.confirm(`确认删除“${lesson.value.topic}”吗？对应学生的课堂观察履历将同步移除。`)) return; await lessonStore.deleteLessonRecord(lesson.value.id) }
watch(() => workbench.studentVersion, () => void loadStudents()); onMounted(loadStudents)
</script>

<template><section v-if="!lesson" class="flex h-full flex-col items-center justify-center p-8 text-center"><span class="flex size-14 items-center justify-center rounded-2xl bg-teal-50 text-teal-700"><BookOpenCheck :size="25" /></span><h1 class="mt-4 text-lg font-semibold text-stone-800">教学记录</h1><p class="mt-2 text-sm text-stone-500">从中间列表选择课程记录，或新增一堂心理课。</p></section><section v-else class="flex h-full min-h-0 flex-col overflow-hidden"><header class="shrink-0 border-b border-stone-200 p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-medium text-teal-700">{{ lesson.grade }}{{ lesson.className }} · 心理课</p><h1 class="mt-1 text-xl font-semibold text-stone-800">{{ lesson.topic }}</h1><p class="mt-2 inline-flex items-center gap-1 text-sm text-stone-500"><CalendarDays :size="14" />{{ lesson.date }}</p></div><div class="flex gap-2"><button type="button" class="inline-flex items-center gap-1 rounded-lg border border-stone-200 px-3 py-2 text-sm text-teal-700 hover:bg-teal-50" @click="lessonStore.openForm(lesson.id)"><PencilLine :size="15" />编辑</button><button type="button" class="rounded-lg p-2 text-rose-600 hover:bg-rose-50" @click="remove"><Trash2 :size="17" /></button></div></div></header><div class="min-h-0 flex-1 overflow-y-auto bg-stone-50/50 p-6"><div class="mx-auto max-w-4xl space-y-5"><section class="rounded-2xl border border-stone-200 bg-white p-5"><h2 class="text-sm font-semibold text-stone-800">教案流程</h2><p class="mt-3 whitespace-pre-wrap text-sm leading-7 text-stone-600">{{ lesson.lessonPlanText || '未记录教案流程。' }}</p></section><section class="rounded-2xl border border-stone-200 bg-white p-5"><h2 class="text-sm font-semibold text-stone-800">课后反思</h2><p class="mt-3 whitespace-pre-wrap text-sm leading-7 text-stone-600">{{ lesson.reflection || '未记录课后反思。' }}</p></section><section class="rounded-2xl border border-amber-100 bg-white p-5"><div class="flex items-center justify-between"><h2 class="text-sm font-semibold text-stone-800">课堂观察学生</h2><span class="rounded-full bg-amber-50 px-2 py-1 text-xs text-amber-800">{{ observedStudents.length }} 人</span></div><p v-if="!observedStudents.length" class="mt-3 text-sm text-stone-400">本次课程未标记需进一步关注的学生。</p><div v-else class="mt-3 grid gap-3 md:grid-cols-2"><article v-for="item in observedStudents" :key="item.studentId" class="rounded-xl bg-amber-50/50 p-4"><div class="flex items-start justify-between gap-3"><div><p class="text-sm font-semibold text-stone-800">{{ item.student?.name }}</p><p class="mt-1 text-xs leading-5 text-stone-600">{{ item.note || '未补充观察说明。' }}</p></div><button type="button" class="shrink-0 rounded-lg border border-amber-300 bg-white px-2.5 py-1.5 text-xs font-semibold text-amber-800 hover:bg-amber-100" @click="item.student && startConsultation(item.student, item.note)">快捷约访</button></div></article></div></section></div></div></section><LessonFormDrawer v-if="lessonStore.isFormOpen" :editing-id="lessonStore.editingLessonId" @saved="lessonStore.fetchLessonRecords()" /></template>
